import React, { useEffect, useState } from 'react';
import AdminNav from '../../Components/AdminNav';

const emptyAd = { title: '', content: '', link: '', poster: '' };

export default function AdvertisementAdmin() {
  const [ads, setAds] = useState([]);
  const [formAd, setFormAd] = useState(emptyAd);
  const [editingId, setEditingId] = useState(null);
  const [message, setMessage] = useState('');

  // Fetch ads
  const fetchAds = async () => {
    try {
      const res = await fetch('http://localhost:5000/advertisements');
      if (res.ok) {
        const data = await res.json();
        setAds(data);
      }
    } catch (error) {
      console.error('Failed to fetch ads', error);
    }
  };

  useEffect(() => {
    fetchAds();
  }, []);

  const resetForm = () => {
    setFormAd(emptyAd);
    setEditingId(null);
    setMessage('');
  };

  const handleChange = e => {
    setFormAd({ ...formAd, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formAd.title || !formAd.content || !formAd.poster) {
      setMessage('Title, content, and poster URL are required');
      return;
    }

    try {
      let res;
      if (editingId) {
        // Update
        res = await fetch(`http://localhost:5000/advertisements/${editingId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formAd),
        });
      } else {
        // Add
        res = await fetch('http://localhost:5000/advertisements', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formAd),
        });
      }

      if (res.ok) {
        setMessage(editingId ? 'Advertisement updated' : 'Advertisement added');
        resetForm();
        fetchAds();
      } else {
        const errorText = await res.text();
        setMessage('Failed to save: ' + errorText);
      }
    } catch (error) {
      setMessage('Error: ' + error.message);
    }
  };

  // Delete ad
  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this advertisement?')) return;
    try {
      const res = await fetch(`http://localhost:5000/advertisements/${id}`, { method: 'DELETE' });
      if (res.ok) {
        setMessage('Advertisement deleted');
        if (editingId === id) resetForm();
        fetchAds();
      } else {
        setMessage('Failed to delete advertisement');
      }
    } catch (error) {
      setMessage('Error: ' + error.message);
    }
  };

  // Start editing
  const startEdit = (ad) => {
    setFormAd({ title: ad.title, content: ad.content, link: ad.link || '', poster: ad.poster });
    setEditingId(ad.id);
    setMessage('');
  };

  return (
    <>
    <AdminNav/>
    <div style={{ maxWidth: '600px', margin: 'auto', padding: '20px' }}>
      <h2>{editingId ? 'Edit Advertisement' : 'Add Advertisement'}</h2>
      {message && <p>{message}</p>}
      <form onSubmit={handleSubmit}>
        <div>
          <label>Title</label><br />
          <input type="text" name="title" value={formAd.title} onChange={handleChange} required />
        </div>
        <div>
          <label>Description</label><br />
          <textarea name="content" value={formAd.content} onChange={handleChange} required rows="4" />
        </div>
        <div>
          <label>Poster URL</label><br />
          <input type="url" name="poster" value={formAd.poster} onChange={handleChange} required placeholder="https://..." />
        </div>
        <div>
          <label>Link (optional)</label><br />
          <input type="url" name="link" value={formAd.link} onChange={handleChange} placeholder="https://..." />
        </div>
        <button type="submit" style={{ marginTop: '10px' }}>{editingId ? 'Update' : 'Add'}</button>
        {editingId && <button type="button" onClick={resetForm} style={{ marginLeft: '10px' }}>Cancel</button>}
      </form>

      <h3 style={{ marginTop: '30px' }}>Existing Advertisements</h3>
      {ads.length === 0 && <p>No advertisements added yet.</p>}
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {ads.map(ad => (
          <li key={ad.id} style={{
            border: '1px solid #ccc', marginBottom: '10px', padding: '10px',
            borderRadius: '6px', display: 'flex', justifyContent: 'space-between',
            alignItems: 'center'
          }}>
            <div style={{flex:1, marginRight: '10px'}}>
              <strong>{ad.title}</strong> - {ad.content.substring(0, 40)}...
            </div>
            <button onClick={() => startEdit(ad)}>Edit</button>
            <button onClick={() => handleDelete(ad.id)} style={{ marginLeft: '5px', color: 'red' }}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
    </>
  );
}
